{
  "packet_id": "H6-T01-3",
  "claim_id": "C055",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C055.component",
    "value": "The trial should be stopped or revised if it compromises required cleaning.",
    "scope": "A conditional operational stopping rule; required cleaning is not further defined in the mapping.",
    "provenance": {
      "refs": [
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P034 explicitly makes compromised required cleaning an independent trigger for stopping or revising the trial."
    }
  },
  "signal_basis": {
    "component_id": "C055.signal_basis",
    "value": "Prospective monitoring of the selected trial identifies unmet cleaning requirements that constitute a compromise to required cleaning.",
    "scope": "The selected trial's cleaning constraint; no inference about delay reduction or the cause of lateness.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P021 specifies monitoring unmet cleaning requirements, and P034 identifies the relevant compromise as a stopping or revision trigger."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C055.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This is an operational constraint applied when its trigger occurs, not a claim requiring an unresolved empirical relation."
    }
  },
  "rationale": "Given an observed compromise to required cleaning, stopping or revising the trial follows from its explicit operational constraint. The claim does not require establishing that the trial reduces delays or causes broader harm.",
  "uncertainty": "Required cleaning is undefined, which may affect identifying the trigger in practice; the stipulated occurrence of that trigger resolves this for the warrant judgment.",
  "anomalies": []
}
